cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int MaxRatePoints = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var rate = Math.Min(BaseRate(tier) + SizeBonus(subtotalCents), MaxRatePoints);
        var discount = (int)((long)subtotalCents * rate / 100);

        return subtotalCents - discount;
    }

    private static int BaseRate(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };

    private static int SizeBonus(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
