s=s.replace("""        // No tier seam exists yet in CalculatePayableTotal; tier is carried for the scenario only.
        _ = tier;

        var actual = new CalculatePayableTotal().For(ToCents(subtotal));""","""        var actual = new CalculatePayableTotal().For(Enum.Parse<LoyaltyTier>(tier), ToCents(subtotal));""")
open(p,'w').write(s)
E
cd ../.. && dotnet test 2>&1 | grep -E "Passed!|Failed|error"

